package com.restro.restaurantservice.service;
import com.restro.restaurantservice.domain.entity.AppUser; import com.restro.restaurantservice.domain.entity.WeekOff; import com.restro.restaurantservice.domain.exception.ResourceNotFoundException; import com.restro.restaurantservice.repository.AppUserRepository; import com.restro.restaurantservice.repository.WeekOffRepository; import com.restro.restaurantservice.web.dto.WeekOffRequest; import com.restro.restaurantservice.web.dto.WeekOffResponse; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class WeekOffService { private final WeekOffRepository repository; private final AppUserRepository users; public WeekOffService(WeekOffRepository repository, AppUserRepository users) { this.repository=repository;this.users=users; }
 @Transactional(readOnly=true) public WeekOffResponse get(Long staffId) { return new WeekOffResponse(staffId,repository.findByStaff_Id(staffId).stream().map(WeekOff::getWeekDay).collect(java.util.stream.Collectors.toSet())); }
 @Transactional public WeekOffResponse save(WeekOffRequest request) { AppUser user=users.findById(request.staffId()).orElseThrow(()->new ResourceNotFoundException("Staff member not found: "+request.staffId())); repository.deleteByStaff_Id(user.getId()); request.days().forEach(day->repository.save(new WeekOff(user,day))); return get(user.getId()); } }
